%\addplot [domain=-6:6,samples=200, color=deepskyblue, line width=1pt, dashed]{-x} node[pos=0.8, below left] {\color{black}{$y=-|x|$}};

\draw[color=black] (axis cs:-3.0,3.0) node {$y = -x^3$};

\draw[color=deepskyblue] (axis cs:3.0,-3.0) node {$y \neq -x^3$};

%Ancors:
%(current page.north east) 
%(current page.south east) 
%(current page.south west) 
%(current page.north west) 

\end{axis}
